def min_coins(coins, n, sum_val):
    dp = [float('inf')] * (sum_val + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        for w in range(coins[i - 1], sum_val + 1):
            dp[w] = min(dp[w], dp[w - coins[i - 1]] + 1)
    return dp[-1] if dp[-1] != float('inf') else -1
