        return 0
    if not coins or value < 0:
        return float('inf')
    # Include the current coin and try to find the solution
    include_coin = min_coins(coins[1:], value - coins[0], count + 1)
    # Exclude the current coin and try to find the solution
    exclude_coin = min_coins(coins, value, count)
    # Return the minimum of including or excluding the coin
    return min(include_coin, exclude_coin)
