def remove_list_range(list, lower, upper):
    # Iterate over a copy of the list to avoid modifying it during iteration
    for sub_list in list.copy():
        # Check if the sub_list is entirely outside the specified range
        if (all(x < lower for x in sub_list)) or (all(x > upper for x in sub_list)):
            # Remove the sublist from the original list
            list.remove(sub_list)
    return list
