def Sum(n):
    prime_divisors = []
    # Divide n by 2 until it's odd
    while n % 2 == 0:
        if 2 not in prime_divisors:
            prime_divisors.append(2)
        n //= 2
    # Check for all odd numbers starting from 3
    for i in range(3, int(n**0.5) + 1, 2):
        # While i divides n, add i and divide n
        while n % i == 0:
            if i not in prime_divisors:
                prime_divisors.append(i)
            n //= i
    # If n is a prime number greater than 2
    if n > 2 and n not in prime_divisors:
        prime_divisors.append(n)
    # Return the sum of all prime divisors
    return sum(prime_divisors)
