def lcs_of_three(str1, str2, str3, m, n, o):
    # Create a 3D table to store the lengths of common subsequences
    dp = [[[0 for _ in range(o + 1)] for _ in range(n + 1)] for _ in range(m + 1)]

    # Fill the 3D table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            for k in range(1, o + 1):
                if str1[i - 1] == str2[j - 1] == str3[k - 1]:
                    dp[i][j][k] = dp[i - 1][j - 1][k - 1] + 1
                else:
                    dp[i][j][k] = max(dp[i - 1][j][k], dp[i][j - 1][k], dp[i][j][k - 1])

    # The maximum length of the common subsequence is in dp[m][n][o]
    return dp[m][n][o]
```

