def lcs_of_three(s1, s2, s3, m, n, p):
    if m < n:
        s1, s2, s3 = s2, s1, s3
        m, n, p = n, m, p

    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            k = 1
            while i + k <= n and j + k <= m and s2[i + k - 1] == s3[j + k - 1]:
                k += 1
            dp[i][j] = max(dp[i][j - 1], dp[i - 1][j], dp[i - 1][j - 1] + k - 1)
    return m + n - dp[n][m]
