def modular_sum(arr, n, m):
    # Return True if there exists a subset with sum divisible by m
    def is_subset_sum(arr, n, m):
        T = [[False for _ in range(n+1)] for _ in range(m+1)]
        # Initialize the first column with True if the sum is 0
        for i in range(n+1):
            T[0][i] = True
        # Fill the table
        for i in range(1, m+1):
            for j in range(1, n+1):
                T[i][j] = T[i][j-1] or (arr[j-1] <= i and T[i-arr[j-1]][j-1])
        return T[m][n]

    # Call the recursive function with the array and parameters
    return is_subset_sum(arr, n, m)
