def modular_sum(nums, n, m):
    if n == 0:
        return True
    dp = [False] * m
    dp[0] = True
    for num in nums:
        for i in range(m - 1, -1, -1):
            if num + i < m:
                dp[i + num] |= dp[i]
            if dp[m - 1]:
                return True
    return False
```

