def get_unique(input_tuple):
    # Initialize an empty dictionary to store unique keys for each value
    unique_keys = {}

    # Iterate over each tuple in the input tuple
    for key, value in input_tuple:
        # If the value is already a key in the dictionary, increment its count
        if value in unique_keys:
            unique_keys[value] += 1
        # Otherwise, add the value as a new key with a count of 1
        else:
            unique_keys[value] = 1

    # Return the dictionary containing unique keys for each value
    return unique_keys
