    sum_val = 1
    # Formula to calculate sum of squares of binomial Coefficients
    for i in range(1, n + 1):
        sum_val = sum_val * (2 * i - 1) * (2 * i + 1) / (4 * i * (2 * i - 1))
    return int(sum_val)
