def set_Right_most_Unset_Bit(n):
    # Count the number of unset bits from right to left
    unset_bits = 0
    while (n & 1) == 0:
        unset_bits += 1
        n >>= 1

    # Set the rightmost unset bit
    if (n ^ (1 << unset_bits)) != 0:
        return (n | (1 << unset_bits))
    else:
        return n
