def get_pairs_count(nums, target, total):
    # Initialize a counter for the pairs
    pair_count = 0
    # Empty dictionary to store numbers and their counts
    num_counts = {}
    # Iterate through each number in the array
    for num in nums:
        # Check if the required pair (target - num) has been seen
        if total - num in num_counts:
            # Add the count of that number to the pair count
            pair_count += num_counts[total - num]
        # Increment the count of the current number in the dictionary
        if num in num_counts:
            num_counts[num] += 1
        else:
            num_counts[num] = 1
    return pair_count
