import math

def min_jumps(arr, n):
    if n <= 1:
        return 0  # No need of jumps if the array has 0 or 1 element
    dp = [math.inf] * n  # Initialize DP array with infinity
    dp[0] = 0  # Base case: no jumps are needed for the first element
    for i in range(1, n):
        for j in range(i):
            if arr[j] + j >= i:
                dp[i] = min(dp[i], dp[j] + 1)
    return dp[n - 1]  # Return the minimum number of jumps to reach the end

