def min_jumps(nums, n):
    if n <= 1:
        return 0  # The first or the only element can be reached in 0 jumps
    jumps = [float('inf')] * n  # Initialize jumps array with infinity
    jumps[0] = 0  # The first element can be reached in 0 jumps
    for i in range(1, n):
        for j in range(i):
            if nums[j] + j >= i:  # Check if the element can reach the current index
                jumps[i] = min(jumps[i], jumps[j] + 1)
    if jumps[n-1] == float('inf'):
        return -1  # If the last element cannot be reached, return -1
    return jumps[n-1]  # Return the minimum number of jumps to reach the end
