def min_jumps(arr, n):
    if n <= 1:
        return 0
    # Initialize the farthest and current jumps positions
    farthest, step, jumps = arr[0], arr[0], 1
    for i in range(1, n):
        if i > farthest:
            # If we can't reach the end with the current number of jumps
            if step == 0:
                return -1
            # Update the step to 0 and get the farthest reachable position from the current
            step = farthest - i
            jumps += 1
        farthest = max(farthest, i + arr[i])
    # If we can't reach the end, return -1
    if step == 0:
        return -1
    return jumps
