def dealnnoy_num(n, m):
    """Calculate the nth Delannoy number."""
    # Base case: the first and last delannoy numbers are 1
    if n == 0 or n == m:
        return 1
    # Recursive case: sum the delannoy numbers of the two preceding rows
    return dealnnoy_num(n, m - 1) + dealnnoy_num(n - 1, m)
