def roman_to_int(s):
    romans = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    int_val = 0
    i = 0

    while i < len(s):
        if i + 1 < len(s) and romans[s[i]] < romans[s[i+1]]:
            int_val += romans[s[i+1]] - romans[s[i]]
            i += 2
        else:
            int_val += romans[s[i]]
            i += 1

    return int_val
