```python
def roman_to_int(roman):
    # Define the value of each Roman numeral
    numeral_values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    # Initialize the integer value
    integer_value = 0
    # Iterate through the Roman numeral string
    for i in range(len(roman)):
        # If the current numeral value is less than the next numeral value, subtract it
        if i < len(roman) - 1 and numeral_values[roman[i]] < numeral_values[roman[i + 1]]:
            integer_value -= numeral_values[roman[i]]
        else:
            # Otherwise, add the numeral value
            integer_value += numeral_values[roman[i]]
    return integer_value
```

