def remove_nested(record):
    # Flatten the tuple by converting each element to a list and flattening with recursion
    def flatten(lst):
        result = []
        for item in lst:
            if isinstance(item, tuple):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result
    # Use recursion to flatten the tuple and then convert back to a tuple
    return tuple(flatten(record))
