def Total_Hamming_Distance(n):
    total_distance = 0
    for i in range(1, n + 1):
        # For each number i from 1 to n, calculate the hamming distance with a loop
        for j in range(i):
            current_distance = 0
            j_binary = bin(j)[2:].zfill(i)  # Convert j to binary and pad with zeros to match the length of i
            i_binary = bin(i)[2:].zfill(i)  # Convert i to binary and pad with zeros to match the length of i
            for bit1, bit2 in zip(j_binary, i_binary):
                if bit1 != bit2:
                    current_distance += 1
            total_distance += current_distance  # Add the current distance to the total
    return total_distance
```

