def modular_sum(arr, n, m):
    # Initialize a 2D list to store intermediate results
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            # If the current element is present in the subset or makes the sum divisible by m
            if arr[i - 1] <= j:
                dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - arr[i - 1]]) % m
            else:
                dp[i][j] = dp[i - 1][j]

    # Check if there exists a subset with sum divisible by m
    return dp[n][m] > 0
```

