def count_duplic(lst):
    window = deque()
    freq = {}
    duplicates = {}
    for num in lst:
        window.append(num)
        if len(window) > 1:
            if window[0] == window[-1]:
                freq[window[0]] = freq.get(window[0], 0) + 1
                duplicates[num] = duplicates.get(num, 0) + 1
        else:
