def largest_subset(nums, n):
    # Initialize a list to keep track of the length of the largest subset ending at each element
    dp = [1] * n
    # Dictionary to store the maximum element for a given length
    max_map = {1: nums[0]}

    # Fill the dp array and max_map
    for i in range(1, n):
        for prev in range(i):
            if nums[i] % nums[prev] == 0 and dp[prev] + 1 > dp[i]:
                dp[i] = dp[prev] + 1
                max_map[dp[i]] = nums[i]

    # Find the maximum length from the dp array
    max_length = max(dp)
    # Build the subset using the max_map
    result = []
    while max_length > 0:
        result.append(max_map[max_length])
        max_length -= 1

    return len(result)
