    # Calculate the sum of the lengths of two sides
    sum_of_two_sides = a + b + c
    # Check if the side lengths satisfy the triangle inequality theorem
    if sum_of_two_sides <= c or sum_of_two_sides <= b or sum_of_two_sides <= a:
