```python
def coin_change(coins, total_currency, no_of_coins):
    table = [[0 for _ in range(total_currency + 1)] for _ in range(no_of_coins + 1)]

    # Base case: it takes 0 coins to make 0 currency
    for i in range(1, no_of_coins + 1):
        table[i][0] = 1

    # Fill the table
    for i in range(1, no_of_coins + 1):
        for j in range(1, total_currency + 1):
            if coins[i-1] <= j:
                table[i][j] = table[i-1][j] + table[i][j-coins[i-1]]
            else:
                table[i][j] = table[i-1][j]

    return table[-1][-1]
```

