def prime_num(n):
    # Check if the number is less than 2
    if n < 2:
        return False
    # Check if the number is 2 or 3
    elif n == 2 or n == 3:
        return True
    # Check if the number is divisible by 2 or 3
    elif n % 2 == 0 or n % 3 == 0:
        return False
    # Check for factors from 5 to the square root of n
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    # If no factors are found, the number is prime
    return True
```

